use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let cents: i64 = input.as_i64().unwrap();
    let pounds = cents / 100;
    let pence = (cents % 100).abs();
    let pounds_str = if cents < 0 {
        format!("-{}.{:02}", pounds.abs(), pence)
    } else {
        format!("{}.{:02}", pounds, pence)
    };
    Value::String(pounds_str)
}
